files.content:
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1a1921;
  --color-card: #282738;
  --color-accent: #f4c038;
  --color-work: #52c41a;
  --color-rest: #1890ff;
  --color-text: #ffffff;
  --color-text-dim: #9aa0a6;
  --color-border: #0e0d14;
  --pixel-shadow: 4px 4px 0px var(--color-border);
  --pixel-shadow-pressed: 1px 1px 0px var(--color-border);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
  display: flex;
  justify-content: center;
}

.timer-card {
  background: var(--color-card);
  width: 100%;
  border: 4px solid var(--color-border);
  box-shadow: 8px 8px 0px #000000;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.header {
  text-align: center;
}

.title {
  font-size: 26px;
  font-weight: 900;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px #000;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 14px;
  color: var(--color-text-dim);
  font-weight: bold;
}

.pixel-art-viewport {
  width: 100%;
  height: 96px;
  background: #121118;
  border: 4px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
}

#pixel-canvas {
  image-rendering: pixelated;
  width: 256px;
  height: 80px;
}

.status-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  width: 100%;
}

.badge-container {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.badge {
  padding: 6px 14px;
  font-size: 16px;
  font-weight: bold;
  text-transform: uppercase;
  border: 3px solid var(--color-border);
  box-shadow: 2px 2px 0px var(--color-border);
}

.badge.work {
  background-color: var(--color-work);
  color: #0b2e04;
}

.badge.rest {
  background-color: var(--color-rest);
  color: #001f4d;
}

.badge.set {
  background-color: #3b3a4f;
  color: var(--color-text);
}

.countdown-display {
  font-size: 54px;
  font-weight: 900;
  letter-spacing: 3px;
  color: #ffffff;
  text-shadow: 4px 4px 0px #000000;
  padding: 8px 16px;
  border: 3px dashed #3b3a4f;
  width: 100%;
  text-align: center;
  background: #181724;
}

.controls-group {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.pixel-btn {
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  padding: 12px 20px;
  border: 3px solid var(--color-border);
  box-shadow: var(--pixel-shadow);
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
  outline: none;
  text-transform: uppercase;
}

.primary-btn {
  background-color: var(--color-accent);
  color: #211903;
}

.secondary-btn {
  background-color: #e5e5ea;
  color: #121216;
}

.text-btn {
  background-color: #4b4a5e;
  color: #ffffff;
}

.pixel-btn:hover {
  filter: brightness(1.1);
}

.pixel-btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: var(--pixel-shadow-pressed);
}

.complete-panel {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 16px 0;
  width: 100%;
}

.complete-message {
  font-size: 28px;
  color: var(--color-accent);
  text-transform: uppercase;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0px #000;
}

.complete-subtext {
  font-size: 16px;
  color: var(--color-text);
}

@media (max-width: 400px) {
  .timer-card {
    padding: 16px;
  }
  .countdown-display {
    font-size: 42px;
  }
  .pixel-btn {
    padding: 10px 14px;
    font-size: 14px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_SETS = 3;
  const WORK_SECONDS = 40;
  const REST_SECONDS = 20;

  let currentSet = 1;
  let currentPhase = 'Work'; // 'Work' | 'Rest'
  let timeLeft = WORK_SECONDS;
  let isRunning = false;
  let timerInterval = null;

  // DOM elements
  const activeView = document.getElementById('active-view');
  const completeView = document.getElementById('complete-view');
  const phaseBadge = document.getElementById('phase-badge');
  const setBadge = document.getElementById('set-badge');
  const countdownEl = document.getElementById('countdown');
  const startBtn = document.getElementById('start-btn');
  const skipBtn = document.getElementById('skip-btn');
  const resetBtn = document.getElementById('reset-btn');
  const restartBtn = document.getElementById('restart-btn');
  const canvas = document.getElementById('pixel-canvas');
  const ctx = canvas.getContext('2d');

  // Pixel Character Animation
  let frame = 0;
  function drawPixelArt() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerX = Math.floor(canvas.width / 2);
    const centerY = Math.floor(canvas.height / 2);
    const pixelSize = 4;

    if (completeView.hidden === false) {
      // Trophy Pixel Art
      ctx.fillStyle = '#f4c038';
      // Trophy Cup
      ctx.fillRect(centerX - 12, centerY - 14, 24, 16);
      ctx.fillRect(centerX - 16, centerY - 14, 4, 8);
      ctx.fillRect(centerX + 12, centerY - 14, 4, 8);
      ctx.fillRect(centerX - 4, centerY + 2, 8, 8);
      ctx.fillRect(centerX - 10, centerY + 10, 20, 6);
      return;
    }

    // Figure drawing (Work: Jumping/Lifting, Rest: Sitting/Breathing)
    if (currentPhase === 'Work') {
      ctx.fillStyle = '#52c41a';
      const bounce = isRunning && (frame % 2 === 0) ? -2 : 0;
      // Head
      ctx.fillRect(centerX - 6, centerY - 18 + bounce, 12, 10);
      // Torso
      ctx.fillRect(centerX - 8, centerY - 8 + bounce, 16, 14);
      // Arms raised
      ctx.fillRect(centerX - 14, centerY - 14 + bounce, 6, 8);
      ctx.fillRect(centerX + 8, centerY - 14 + bounce, 6, 8);
      // Legs spread
      ctx.fillRect(centerX - 10, centerY + 6 + bounce, 6, 12);
      ctx.fillRect(centerX + 4, centerY + 6 + bounce, 6, 12);
    } else {
      ctx.fillStyle = '#1890ff';
      const breathe = isRunning && (frame % 2 === 0) ? 1 : 0;
      // Head
      ctx.fillRect(centerX - 6, centerY - 12 + breathe, 12, 10);
      // Torso
      ctx.fillRect(centerX - 6, centerY - 2 + breathe, 12, 12);
      // Arms at sides
      ctx.fillRect(centerX - 10, centerY + breathe, 4, 10);
      ctx.fillRect(centerX + 6, centerY + breathe, 4, 10);
      // Legs bent/resting
      ctx.fillRect(centerX - 8, centerY + 10, 16, 4);
    }
  }

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    const mm = m < 10 ? '0' + m : m;
    const ss = s < 10 ? '0' + s : s;
    return `${mm}:${ss}`;
  }

  function updateDisplay() {
    countdownEl.textContent = formatTime(timeLeft);
    phaseBadge.textContent = currentPhase;
    phaseBadge.className = `badge ${currentPhase.toLowerCase()}`;
    setBadge.textContent = `Set ${currentSet} / ${TOTAL_SETS}`;
    drawPixelArt();
  }

  function tick() {
    frame++;
    if (timeLeft > 1) {
      timeLeft--;
    } else {
      nextPhase();
    }
    updateDisplay();
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    startBtn.textContent = 'Pause';
    timerInterval = setInterval(tick, 1000);
  }

  function pauseTimer() {
    if (!isRunning) return;
    isRunning = false;
    startBtn.textContent = 'Start';
    clearInterval(timerInterval);
  }

  function nextPhase() {
    if (currentPhase === 'Work') {
      currentPhase = 'Rest';
      timeLeft = REST_SECONDS;
    } else {
      if (currentSet < TOTAL_SETS) {
        currentSet++;
        currentPhase = 'Work';
        timeLeft = WORK_SECONDS;
      } else {
        completeWorkout();
        return;
      }
    }
    updateDisplay();
  }

  function completeWorkout() {
    pauseTimer();
    activeView.hidden = true;
    completeView.hidden = false;
    drawPixelArt();
  }

  function resetWorkout() {
    pauseTimer();
    currentSet = 1;
    currentPhase = 'Work';
    timeLeft = WORK_SECONDS;
    frame = 0;
    activeView.hidden = false;
    completeView.hidden = true;
    updateDisplay();
  }

  // Event Listeners
  startBtn.addEventListener('click', () => {
    if (isRunning) {
      pauseTimer();
    } else {
      startTimer();
    }
  });

  skipBtn.addEventListener('click', () => {
    nextPhase();
  });

  resetBtn.addEventListener('click', resetWorkout);
  restartBtn.addEventListener('click', resetWorkout);

  // Keyboard accessibility shortcuts (Space to toggle, 's' to skip, 'r' to reset)
  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'BUTTON') return; // Allow normal button spacebar behavior
    if (e.code === 'Space') {
      e.preventDefault();
      if (completeView.hidden) {
        if (isRunning) pauseTimer(); else startTimer();
      } else {
        resetWorkout();
      }
    } else if (e.key === 's' || e.key === 'S') {
      if (completeView.hidden) nextPhase();
    } else if (e.key === 'r' || e.key === 'R') {
      resetWorkout();
    }
  });

  // Initialize
  resetWorkout();
});
